--
-- Name: vw_pdv_bipagem; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_pdv_bipagem AS
 SELECT p.id,
    p.codigo_barra,
    p.descricao,
    p.marca,
    p.preco_venda,
    p.quantidade_estoque,
    p.cst_icms,
    p.preco_custo,
    COALESCE(t.aliquota_estimada, 13.45) AS aliquota_aplicada,
    round(((p.preco_venda * COALESCE(t.aliquota_estimada, 13.45)) / (100)::numeric), 2) AS valor_imposto_item
   FROM (public.tabela_produtos p
     LEFT JOIN public.config_tributaria t ON (((p.cst_icms)::text = (t.cst_icms)::text)));


ALTER VIEW public.vw_pdv_bipagem OWNER TO postgres;

